      H.ops.writeWork,
      H.ops.resolve(releaseApproval, H.halts.interrupted, H.halts.definitionChanged),
      H.ops.readTelemetry,
    ],
  }))
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));

