      .step('build', builder, ctx => ({
        task: `${ctx.unit.attributes.title}\n${ctx.unit.attributes.description}\nOwner notes: ${ctx.unit.attributes.notes.join('; ')}\nOpen deficits:\n${ctx.steps.round.join('\n')}`,
