    H.ops.workCancel,
    H.ops.resolve(ownerDecision, ownerReview),
    H.ops.memoryRead,
    H.ops.memoryWrite,
    H.ops.telemetryRead,
    H.ops.accountsRead,
    H.ops.accountsShare,
    H.operation('production-health', productionProbe),
