    when: { kinds: [backup] },
  }));

const scheduler = H.scheduler('operations')
  .expedite(incidentLane, { holds: [backupLane] })
  .standard(heartbeatLane, backupLane, renewalLane);

const operatorApi = http.controlApi('operator-api', {
  port: H.slot.port(0),
  token: H.env('OPS_API_TOKEN'),
