const subscription = claudeCode.subscription('data-subscription', { token: H.env('CLAUDE_TOKEN'), quota });
const pool = H.pool('data').accounts(subscription);
const sonnet = claudeCode.model('sonnet', { id: 'claude-sonnet-4-5' });

