  .step('decide', decideWinner, ctx => ctx.steps.hourly)
  .exit('aWins', ctx => ctx.steps.decide.winner === 'a')
  .exit('bWins', ctx => ctx.steps.decide.winner === 'b')
  .exit('inconclusive');

const experimentLane = H.lane('experiments', experimentKind)
